import { readFileSync } from 'node:fs';
import sharp from 'sharp';
import { describe, expect, it } from 'vitest';
import {
  PAGE_WIDTH,
  renderImagePage,
  renderPdfPages,
  stampWatermark,
  thumbnailOf,
  type RenderedPage,
} from '#src/lib/preview-render';

// Generated by test/fixtures/uploads/generate.py (pdf skill: reportlab + pypdf).
const VALID_PDF = readFileSync('test/fixtures/uploads/valid.pdf');

function isWebp(body: Buffer): boolean {
  return (
    body.subarray(0, 4).toString('latin1') === 'RIFF' &&
    body.subarray(8, 12).toString('latin1') === 'WEBP'
  );
}

function whitePng(width: number, height: number): Promise<Buffer> {
  return sharp({ create: { width, height, channels: 3, background: '#ffffff' } })
    .png()
    .toBuffer();
}

/** Share of pixels that are not white, and of those, how many lean green (the stamp's ink). */
async function inkOf(webp: Buffer) {
  const { data, info } = await sharp(webp)
    .removeAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  let inked = 0;
  let green = 0;
  for (let i = 0; i < data.length; i += info.channels) {
    const [r, g, b] = [data[i]!, data[i + 1]!, data[i + 2]!];
    if (r < 245 || g < 245 || b < 245) {
      inked++;
      if (g >= r && g >= b) green++;
    }
  }
  const pixels = data.length / info.channels;
  return { inked: inked / pixels, greenShare: inked ? green / inked : 0 };
}

describe('view-only page rendering', () => {
  it('stamps the watermark across a blank page', async () => {
    const page = await stampWatermark(await whitePng(1240, 1754));
    expect(isWebp(page.webp)).toBe(true);
    const ink = await inkOf(page.webp);
    // A blank page comes back covered by the tiled stamp: several percent of it, all green.
    expect(ink.inked).toBeGreaterThan(0.03);
    expect(ink.greenShare).toBeGreaterThan(0.9);
  });

  it('watermarks the corners too, so cropping a margin does not remove it', async () => {
    const page = await stampWatermark(await whitePng(1240, 1754));
    const quarter = { width: 620, height: 877 };
    for (const [left, top] of [
      [0, 0],
      [620, 0],
      [0, 877],
      [620, 877],
    ] as const) {
      const corner = await sharp(page.webp)
        .extract({ left, top, ...quarter })
        .webp()
        .toBuffer();
      expect((await inkOf(corner)).inked).toBeGreaterThan(0.02);
    }
  });

  it('renders every PDF page at reading width, watermarked', async () => {
    const pages: { page: RenderedPage; n: number }[] = [];
    const { totalPages } = await renderPdfPages(VALID_PDF, 500, (page, n) => {
      pages.push({ page, n });
      return Promise.resolve();
    });
    expect(totalPages).toBeGreaterThan(0);
    expect(pages.map((p) => p.n)).toEqual(Array.from({ length: totalPages }, (_, i) => i + 1));
    const first = pages[0]!.page;
    expect(isWebp(first.webp)).toBe(true);
    expect(first.width).toBe(PAGE_WIDTH);
    expect(first.height).toBeGreaterThan(first.width); // A4 portrait
    expect((await inkOf(first.webp)).greenShare).toBeGreaterThan(0.3);
  });

  it('stops at the page cap but reports the full length', async () => {
    const seen: number[] = [];
    const { totalPages } = await renderPdfPages(VALID_PDF, 0, (_page, n) => {
      seen.push(n);
      return Promise.resolve();
    });
    expect(seen).toEqual([]);
    expect(totalPages).toBeGreaterThan(0);
  });

  it('throws on a damaged PDF', async () => {
    await expect(
      renderPdfPages(Buffer.from('%PDF-1.7 broken'), 5, async () => {}),
    ).rejects.toThrow();
  });

  it('renders an image upload as one watermarked page, at most the reading width', async () => {
    const page = await renderImagePage(await whitePng(3000, 1500));
    expect(page.width).toBe(PAGE_WIDTH);
    expect(page.height).toBe(620);
    expect((await inkOf(page.webp)).inked).toBeGreaterThan(0.03);
  });

  it('makes the card thumbnail from the watermarked page', async () => {
    const page = await stampWatermark(await whitePng(1240, 1754));
    const thumb = await thumbnailOf(page.webp);
    expect(isWebp(thumb)).toBe(true);
    expect((await sharp(thumb).metadata()).width).toBe(720);
    expect((await inkOf(thumb)).inked).toBeGreaterThan(0.03);
  });
});
